// Authored-asset registry: hand-written copy and thumbnails for portfolio
// projects, read by the deterministic sync but never regenerated by it.
//
// Why a registry instead of generation: the sync must produce byte-identical
// output for identical inputs, otherwise the weekly workflow opens a PR every
// week forever. Deriving the narrative through a model call would break that, so
// the copy is authored once, reviewed by hand and committed here; the sync treats
// it as an input.
//
// Precedence, owned here and documented in README.md:
//
//   manual registry entry  >  authored asset  >  derived value
//
// A manual registry entry (scripts/portfolio-sources.json and friends) is already
// hand-written, so an authored asset never decorates it: targeting one aborts the
// run instead of silently losing to it. Assets decorate discovered sources, whose
// copy and thumbnail are derived.
//
// Fail-closed: a malformed registry, an unknown key, a duplicate identity or an
// asset that matches no source aborts the run before any write, so a typo can
// never silently ship a project with the derived boilerplate still in place.

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { fail } from "./portfolio-registry.mjs";

const scriptDir = path.dirname(fileURLToPath(import.meta.url));

export const AUTHORED_ASSETS_PATH = path.join(scriptDir, "..", "portfolio-authored-assets.json");

// `slug` is deliberately absent: the slug is the public URL, so changing it is a
// redirect migration, not an authoring edit. It stays owned by the source.
const ASSET_KEYS = new Set(["id", "github", "card", "seo", "thumbnail"]);
const CARD_KEYS = new Set(["nombre", "descripcion"]);
const SEO_KEYS = new Set(["categoria", "tituloSeo", "descripcionSeo", "desafio", "enfoque"]);
const KEBAB_CASE = /^[a-z0-9-]+$/;

function requireNonEmptyString(value, label) {
  if (typeof value !== "string" || !value.trim()) {
    fail(`authored asset ${label} must be a non-empty string`);
  }
  return value.trim();
}

function rejectUnknownKeys(object, allowed, label) {
  for (const key of Object.keys(object)) {
    if (!allowed.has(key)) {
      fail(`authored asset ${label} has unknown key "${key}"`);
    }
  }
}

function validateAsset(asset, position) {
  const label = `#${position}`;
  if (!asset || typeof asset !== "object" || Array.isArray(asset)) {
    fail(`authored asset ${label} must be an object`);
  }
  rejectUnknownKeys(asset, ASSET_KEYS, label);

  const id = asset.id;
  if (typeof id !== "string" || !KEBAB_CASE.test(id)) {
    fail(`authored asset ${label}: "id" must be a kebab-case string`);
  }

  if (asset.github !== undefined) {
    if (typeof asset.github?.owner !== "string" || typeof asset.github?.repo !== "string") {
      fail(`authored asset ${id}: "github" must be { owner, repo }`);
    }
    requireNonEmptyString(asset.github.owner, `${id}.github.owner`);
    requireNonEmptyString(asset.github.repo, `${id}.github.repo`);
  }

  if (asset.card !== undefined) {
    if (!asset.card || typeof asset.card !== "object" || Array.isArray(asset.card)) {
      fail(`authored asset ${id}: "card" must be an object`);
    }
    rejectUnknownKeys(asset.card, CARD_KEYS, `${id}.card`);
    for (const field of Object.keys(asset.card)) {
      requireNonEmptyString(asset.card[field], `${id}.card.${field}`);
    }
  }

  if (asset.seo !== undefined) {
    if (!asset.seo || typeof asset.seo !== "object" || Array.isArray(asset.seo)) {
      fail(`authored asset ${id}: "seo" must be an object`);
    }
    if ("slug" in asset.seo) {
      fail(
        `authored asset ${id}: "seo.slug" is not authorable — the slug is the public URL and changing it is a redirect migration`
      );
    }
    rejectUnknownKeys(asset.seo, SEO_KEYS, `${id}.seo`);
    for (const field of Object.keys(asset.seo)) {
      requireNonEmptyString(asset.seo[field], `${id}.seo.${field}`);
    }
  }

  if (asset.thumbnail !== undefined) {
    if (asset.thumbnail?.authored !== true) {
      fail(`authored asset ${id}: "thumbnail" must be { authored: true } when present`);
    }
  }

  return asset;
}

// Reads and validates the committed authored-asset registry. A missing file is an
// empty registry (the mechanism is optional), matching the other registries; a
// present but malformed file aborts the run.
export function loadAuthoredAssets({ filePath = AUTHORED_ASSETS_PATH } = {}) {
  if (!fs.existsSync(filePath)) return [];
  let parsed;
  try {
    parsed = JSON.parse(fs.readFileSync(filePath, "utf8"));
  } catch (error) {
    fail(`portfolio-authored-assets.json is not valid JSON: ${error.message}`);
  }
  if (!parsed || typeof parsed !== "object" || !Array.isArray(parsed.assets)) {
    fail('portfolio-authored-assets.json must be an object with an "assets" array');
  }

  const assets = parsed.assets.map(validateAsset);
  const seenIds = new Set();
  const seenRepos = new Set();
  for (const asset of assets) {
    if (seenIds.has(asset.id)) {
      fail(`Duplicate authored asset id "${asset.id}"`);
    }
    seenIds.add(asset.id);
    if (asset.github) {
      const repo = repoKey(asset.github);
      if (seenRepos.has(repo)) {
        fail(`Duplicate authored asset repository "${repo}"`);
      }
      seenRepos.add(repo);
    }
  }
  return assets;
}

function repoKey({ owner, repo }) {
  return `${owner.toLowerCase()}/${repo.toLowerCase()}`;
}

// Identity match, in priority order: the source slug first, then the GitHub
// owner/repo when both sides declare it (a repository rename keeps the repository
// identity, so this survives a rename that would change the slug). The slug is the
// primary key, so it wins over a repository match instead of file order deciding.
export function findAuthoredAsset({ assets = [], source = {} } = {}) {
  const byId = assets.find((asset) => asset.id === source.id);
  if (byId) return byId;
  if (!source.github) return null;
  const sourceRepo = repoKey(source.github);
  return assets.find((asset) => asset.github && repoKey(asset.github) === sourceRepo) ?? null;
}

// Decorates the resolved source list with the authored assets.
//
// Returns a new list. Sources with no authored asset are returned as the same
// object references (the caller relies on object identity to tell which
// discovered sources actually got published, so undecorated sources must not be
// copied). The input list and its sources are never mutated.
//
// Aborts when an asset matches no source (a typo must not silently no-op) or when
// an asset targets a manual registry entry (that entry is already hand-written).
export function applyAuthoredAssets({ sources = [], manualSources = [], assets = [] } = {}) {
  const manualIds = new Set(manualSources.map((source) => source.id));
  const matched = new Set();
  const decorated = [];

  for (const source of sources) {
    const asset = findAuthoredAsset({ assets, source });
    if (!asset) {
      decorated.push(source);
      continue;
    }
    matched.add(asset.id);
    if (manualIds.has(source.id)) {
      fail(
        `authored asset "${asset.id}" targets a manual registry entry; the registry entry is already hand-written, so keep the copy in one place`
      );
    }
    decorated.push({
      ...source,
      ...(asset.card ? { card: { ...source.card, ...asset.card } } : {}),
      ...(asset.seo ? { seo: { ...source.seo, ...asset.seo } } : {}),
      ...(asset.thumbnail?.authored
        ? { thumbnail: { ...source.thumbnail, authored: true } }
        : {}),
    });
  }

  for (const asset of assets) {
    if (!matched.has(asset.id)) {
      fail(`authored asset "${asset.id}" matches no portfolio source`);
    }
  }
  return decorated;
}
